import functools

def _parse(v):
    core = v.split('+', 1)[0]
    if '-' in core:
        main, pre = core.split('-', 1)
    else:
        main, pre = core, None
    major, minor, patch = (int(x) for x in main.split('.'))
    return (major, minor, patch), pre

def _pre_ids(pre):
    return pre.split('.')

def _cmp_id(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if a_num and not b_num:
        return -1
    if not a_num and b_num:
        return 1
    return (a > b) - (a < b)

def _compare(v1, v2):
    (m1, pre1), (m2, pre2) = _parse(v1), _parse(v2)
    core1, pre1s = _parse(v1)
    core2, pre2s = _parse(v2)
    if core1 != core2:
        return -1 if core1 < core2 else 1
    if pre1s is None and pre2s is None:
        return 0
    if pre1s is None:
        return 1
    if pre2s is None:
        return -1
    ids1 = _pre_ids(pre1s)
    ids2 = _pre_ids(pre2s)
    for a, b in zip(ids1, ids2):
        c = _cmp_id(a, b)
        if c != 0:
            return c
    if len(ids1) != len(ids2):
        return -1 if len(ids1) < len(ids2) else 1
    return 0

def semver_sort(versions):
    return sorted(versions, key=functools.cmp_to_key(_compare))

